{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")
    if "nodes" not in payload or "required_symbols" not in payload:
        raise ValueError("missing required payload fields")

    nodes = payload["nodes"]
    required_symbols = payload["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) or not symbol for symbol in required_symbols):
        raise ValueError("required symbols must be non-empty strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("required symbols must be unique")

    by_id = {}
    normalized = []
    fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in fields):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id or node_id in by_id:
            raise ValueError("node IDs must be unique non-empty strings")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a non-empty string")
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbol must be a non-empty string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if utility != utility or utility in (float("inf"), float("-inf")):
            raise ValueError("utility must be finite")
        item = {
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
            "utility": utility,
        }
        by_id[node_id] = item
        normalized.append(item)

    roots = [node for node in normalized if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("tree must have exactly one depth-zero root")
    root_id = roots[0]["id"]

    children = {node_id: [] for node_id in by_id}
    for node in normalized:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent references an unknown node")
        if by_id[parent]["depth"] + 1 != node["depth"]:
            raise ValueError("node depth is inconsistent with its parent")
        children[parent].append(node["id"])

    visited = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError("nodes must form a tree")
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(normalized):
        raise ValueError("all nodes must be connected to the root")

    required = set(required_symbols)
    represented = {node["symbol"] for node in normalized}
    if not required.issubset(represented):
        raise ValueError("every required symbol must be represented")

    retained = set(by_id)
    removal_order = []
    candidates = sorted(normalized, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        tentative = retained - {node_id}
        remaining_symbols = {by_id[item_id]["symbol"] for item_id in tentative}
        if not required.issubset(remaining_symbols):
            continue
        retained = tentative
        removal_order.append(node_id)

    grammar_valid = root_id in retained and all(
        node_id == root_id or by_id[node_id]["parent"] in retained
        for node_id in retained
    )
    remaining_symbols = {by_id[node_id]["symbol"] for node_id in retained}
    interestingness_preserved = required.issubset(remaining_symbols)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
        "grammar_valid": grammar_valid,
        "interestingness_preserved": interestingness_preserved,
        "registered_candidate_order": True,
        "stable_ties": True,
    }
"}
